// Hand-rolled hooks for endpoints that aren't (yet) generated by Orval.
// These call the same `customFetch` mutator the orval client uses, so
// session cookies / base URL / error handling stay consistent. When
// these endpoints are eventually moved into openapi.yaml the hooks here
// can be replaced with the generated equivalents.

import { useMutation, useQuery } from "@tanstack/react-query";
import { customFetch } from "@workspace/api-client-react";

// ---------- Asset extension fields ----------

// Server includes these on every Asset payload; the orval-generated
// `Asset` type doesn't know about them yet, so we widen at the call
// site via this intersection.
export type AssetExt = {
  category: "TRUCK" | "TRAILER" | "HANDHELD" | "CUSTOM";
  customCategoryLabel: string | null;
  quantity: number;
  assignedCrewId: number | null;
  assignedCrewName: string | null;
  lastAssignedAt: string | null;
  lastAssignedByUserId: number | null;
  lastAssignedByName: string | null;
  // Trailers + quantity-tracked items report `usageUnit: "NONE"` and
  // a sentinel `usageUntilDue` value. UIs gate on usageUnit before
  // formatting the "X miles until due" string.
  usageUnit: "MILES" | "HOURS" | "NONE";
  // Period rollups for the cost-period selector.
  mtdSpendCents: number;
  last30SpendCents: number;
  // Hero image + holder fields (added in the v2 fleet pass).
  hasImage: boolean;
  imageDataUrl: string | null;
  currentHolderUserId: number | null;
  currentHolderName: string | null;
  currentCheckoutId: number | null;
  currentCheckoutSince: string | null;
  lastHolderUserId: number | null;
  lastHolderName: string | null;
  lastCheckedOutAt: string | null;
  // Storage location for equipment (e.g. "Lawn Yard", "Tree Yard").
  // Null for trucks — they move between sites.
  location: string | null;
  // Purchase price in cents — surfaced here so the UI can display and
  // edit it even though the orval-generated Asset type may not include it.
  purchasePriceCents: number | null;
  // Identifier (VIN for trucks, serial for equipment) + spec fields
  // the Edit Asset dialog pre-fills from. All already present in the
  // /assets payload.
  identifier: string | null;
  plate: string | null;
  equipmentType: string | null;
  purchaseDate: string | null;
  serviceIntervalUsage: number;
  currentUsage: number;
  // Insurance schedule fields (trucks/trailers only; null for equipment)
  year: number | null;
  statedValueCents: number | null;
  gvwGcwLbs: number | null;
  garagingState: string | null;
  operatingRadiusMiles: number | null;
  insuranceVehNumber: number | null;
  bodyTypeCode: string | null;
};

// ---------- Asset image ----------
export function useAssetImage(slug: string, enabled = true) {
  return useQuery({
    queryKey: ["asset-image", slug] as const,
    queryFn: () =>
      customFetch<{ imageDataUrl: string | null }>(
        `/api/assets/${encodeURIComponent(slug)}/image`,
      ),
    enabled: enabled && slug.length > 0,
  });
}

export function useUpdateAssetImage(slug: string) {
  return useMutation({
    mutationFn: (imageDataUrl: string | null) =>
      customFetch<{ ok: boolean; hasImage: boolean }>(
        `/api/assets/${encodeURIComponent(slug)}/image`,
        {
          method: "PUT",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ imageDataUrl }),
        },
      ),
  });
}

