// ---------- Crews ----------
// `Crew` is the list-summary shape from GET /crews. The counts +
// lead/department fields power the at-a-glance grid on the Crews page;
// the older `{ id, name }` consumers (dropdowns, asset assignment) keep
// working since they only read those two fields.
export type Crew = {
  id: number;
  name: string;
  leadUserId?: number | null;
  leadName?: string | null;
  departmentId?: number | null;
  departmentLabel?: string | null;
  memberCount?: number;
  truckCount?: number;
  equipmentCount?: number;
};
export type CrewMember = {
  userId: number;
  fullName: string;
  role: string;
  department: string;
};
export type CrewDetail = {
  id: number;
  name: string;
  leadUserId: number;
  departmentId: number | null;
  members: CrewMember[];
  trucks: Array<{ id: number; name: string; status: string; slug: string | null }>;
  equipment: Array<{ id: number; name: string; type: string; status: string; slug: string | null }>;
};

const CREWS_KEY = ["crews"] as const;

export function useListCrews() {
  return useQuery({
    queryKey: CREWS_KEY,
    queryFn: () => customFetch<{ crews: Crew[] }>("/api/crews"),
  });
}

export function getCrewDetailKey(id: number) {
  return ["crew", id] as const;
}

export function useCrewDetail(id: number) {
  return useQuery({
    queryKey: getCrewDetailKey(id),
    queryFn: () => customFetch<{ crew: CrewDetail }>(`/api/crews/${id}`),
    enabled: id > 0,
  });
}

